UPDATE BOK_DEAL_ACCOUNTING_DETAIL
set 
    BOK_DETAIL_ID = #{item.newBokDetailId,jdbcType=VARCHAR},
    UPDATE_USER = #{item.updateUser,jdbcType=VARCHAR},
    UPDATE_TIME = #{item.updateTime,jdbcType=TIMESTAMP}
where
    BOK_DETAIL_ID = #{item.oldBokDetailId,jdbcType=VARCHAR}
    AND BOOKSET_ID = #{item.booksetId,jdbcType=VARCHAR}

